"use client";
/**
 * Demo stage: Anna's phone and Dr. Keller's handover side by side,
 * both driven by the same state so a decision on the phone updates the sheet live.
 * Single views: /anna and /keller.
 */
import { AnnaApp } from "@/components/AnnaApp";
import { KellerSheet } from "@/components/KellerSheet";
import { useStafette } from "@/lib/useStafette";

export default function DemoPage() {
  const { state, decide, reset, live, connected } = useStafette();

  return (
    <main className="stage">
      <div>
        <p className="stage-label">Was Anna sieht</p>
        <AnnaApp state={state} onDecide={decide} onReset={reset} />
      </div>
      <div className="stage-col--doc">
        <p className="stage-label">Was Dr. Keller bekommt</p>
        <KellerSheet state={state} />
      </div>
      <span className={`status-pill ${live && connected ? "status-pill--live" : ""}`}>
        {live ? (connected ? "Live verbunden" : "Verbinde …") : "Demo-Daten"}
      </span>
    </main>
  );
}
"use client";
import { AnnaApp } from "@/components/AnnaApp";
import { useStafette } from "@/lib/useStafette";

export default function AnnaPage() {
  const { state, decide, reset } = useStafette();
  return (
    <main className="stage">
      <AnnaApp state={state} onDecide={decide} onReset={reset} />
    </main>
  );
}
"use client";
import { KellerSheet } from "@/components/KellerSheet";
import { useStafette } from "@/lib/useStafette";

export default function KellerPage() {
  const { state } = useStafette();
  return (
    <main className="stage">
      <div className="stage-col--doc">
        <KellerSheet state={state} />
      </div>
    </main>
  );
}
"use client";
/**
 * Connects the dashboard to the Stafette backend.
 *
 * - With NEXT_PUBLIC_API_URL set: loads GET /state, then listens to GET /events (SSE).
 *   Each SSE message is `{"state": StafetteState}`. Answers go to POST /approvals/:id.
 * - Without it: runs fully on mock data, so the frontend can be built and demoed alone.
 */
import { useCallback, useEffect, useState } from "react";
import { applyDecision, initialState } from "./mock";
import type { StafetteState } from "./types";

const API = process.env.NEXT_PUBLIC_API_URL;

export function useStafette() {
  const [state, setState] = useState<StafetteState>(initialState);
  const [connected, setConnected] = useState(false);

  useEffect(() => {
    if (!API) return;
    let es: EventSource | null = null;

    fetch(`${API}/state`)
      .then((r) => r.json())
      .then((s: StafetteState) => setState(s))
      .catch(() => {});

    es = new EventSource(`${API}/events`);
    es.onopen = () => setConnected(true);
    es.onerror = () => setConnected(false);
    es.onmessage = (msg) => {
      try {
        const data = JSON.parse(msg.data);
        if (data.state) setState(data.state as StafetteState);
      } catch {
        /* ignore malformed messages */
      }
    };
    return () => es?.close();
  }, []);

  const decide = useCallback(
    async (approve: boolean) => {
      const approvalId = state.approval?.id;
      if (!approvalId) return;
      if (API) {
        await fetch(`${API}/approvals/${approvalId}`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ approve }),
        });
      } else {
        setState((s) => applyDecision(s, approve));
      }
    },
    [state.approval?.id],
  );

  const reset = useCallback(async () => {
    if (API) {
      await fetch(`${API}/reset`, { method: "POST" }).catch(() => {});
    } else {
      setState(initialState);
    }
  }, []);

  return { state, decide, reset, live: Boolean(API), connected };
}
"use client";
/**
 * The patient's app (Anna). Three screens:
 *   1. Start: say or type the goal
 *   2. Mandate: plain-language summary of what the agent may do, then sign
 *   3. Progress: timeline of sources, the one open question, optional protocol
 * Screens 1–2 are local UI state; screen 3 renders the live StafetteState.
 */
import { useState } from "react";
import type { StafetteState, Station } from "@/lib/types";
import { Logo } from "./Logo";
import { CheckIcon, MicIcon, ShieldIcon } from "./Icons";

type Screen = "start" | "heard" | "mandate" | "progress";

type Props = {
  state: StafetteState;
  onDecide: (approve: boolean) => void;
  onReset: () => void;
};

export function AnnaApp({ state, onDecide, onReset }: Props) {
  const [screen, setScreen] = useState<Screen>("start");
  const [showLog, setShowLog] = useState(false);

  const restart = () => {
    setScreen("start");
    setShowLog(false);
    onReset();
  };

  return (
    <div className="phone">
      <header className="phone-head">
        <Logo />
        {screen !== "progress" && (
          <div className="steps" aria-label={screen === "mandate" ? "Schritt 2 von 2" : "Schritt 1 von 2"}>
            <span className="on" />
            <span className={screen === "mandate" ? "on" : ""} />
          </div>
        )}
      </header>

      {screen === "start" && (
        <>
          <div className="phone-body phone-body--start">
            <h1 className="h1">Neue Hausärztin? Ich hole Ihre Unterlagen.</h1>
            <p className="muted">Sagen Sie mir, zu wem Sie wechseln und wo Sie bisher in Behandlung waren.</p>
